import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Running VLAs at Real-time Speed","description":"","frontmatter":{"title":"Running VLAs at Real-time Speed","arxiv":"2510.26742","date":"2025-10-30","authors":"Yunchao Ma, Yizhuang Zhou, Yunhuan Yang, Tiancai Wang, Haoqiang Fan","categories":"cs.RO","topics":"具身智能, 推理加速, 实时控制","outline":[2,2]},"headers":[],"relativePath":"papers/2510.26742.md","filePath":"papers/2510.26742.md","lastUpdated":null}'),e={name:"papers/2510.26742.md"};function l(i,s,r,m,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="running-vlas-at-real-time-speed" tabindex="-1">Running VLAs at Real-time Speed <a class="header-anchor" href="#running-vlas-at-real-time-speed" aria-label="Permalink to &quot;Running VLAs at Real-time Speed&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2510.26742" target="_blank" rel="noreferrer">2510.26742</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-10-30</td></tr><tr><td><strong>作者</strong></td><td>Yunchao Ma, Yizhuang Zhou, Yunhuan Yang, Tiancai Wang, Haoqiang Fan</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用 CUDA graph 消除 CPU 开销、等价改写计算图、逐核调优 GEMM 三步，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 级多视角 VLA 在单张 RTX 4090 上压到双视角 27.3 ms，并据此提出 30 Hz 视觉 / 480 Hz 动作 / &lt;1 Hz 文本的全流式推理设想。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>十亿参数级 VLA 的一次前向通常要几百毫秒，这使得「抓住正在下落的物体」这类需要快速反应的任务被默认排除在 VLA 的能力范围之外，只能交给传统控制器。论文把这个门槛量化得非常干脆：<strong>33 ms ≈ 1/30 秒是分水岭</strong>。低于它，30 FPS 相机流的每一帧都能被完整处理；哪怕做到 34 ms，也必须时不时丢帧，而一旦需要检测的事件恰好落在被丢的那一帧上，延迟就要整整多出一个帧周期。</p><p>这个问题重要的原因不在于「快一点更好」，而在于它决定了一整类任务是否可做。论文的核心观察是：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 级模型在单张消费级显卡上<strong>本来就跑得动实时</strong>，此前的慢并非模型本身的算力需求所致，而是推理实现里的开销所致。作者实测的官方 openpi 实现双视角为 53.7 ms，优化后为 27.3 ms，而按 roofline 算出的硬件下界是 19.7 ms——也就是说，可省的部分远大于此前的认知。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有的加速工作可分三类。<strong>手工核与厂商库</strong>：XLA、TensorRT、CUTLASS 靠算子调度、核自动调优与高度优化的 GEMM 原语提速；FlashAttention 用分块把注意力的 HBM↔SRAM I/O 降下来，FlashDecoding 针对长上下文自回归解码把注意力拆成两次归约。作者的批评是：这些工作把调度与算子融合留给程序员，因而在核启动开销与反复的全局内存搬运上仍有显著损失；针对注意力的优化也忽略了模型的其余部分（FFN），而在 VLA 里 FFN 才是大头。<strong>调度式编译器</strong>（TVM 类）把算法与执行调度解耦，但仍需为每个算子显式给出算法规格，效果被规格与调度的质量封顶。<strong>超优化</strong>（Mirage、Neptune）在线程/分块/算子多层做代数与调度变换的联合搜索，但依赖统计等价性检查，且搜索时间长、加速比有限，不适合实时 VLA。</p><p>值得补充的是另一条正交的路线：VLA 社区的主流加速手段是<strong>减少计算量</strong>——剪层、量化、token 剪枝与缓存，<a href="/notes/papers/2510.24795">高效 VLA 综述</a> 对此有系统梳理。本文的立场与它们相反：<strong>一个 token 都不减、一个比特都不降</strong>（全程 BF16），只把实现做对。这使它成为所有算法级加速工作的公平基线——若不先把实现开销榨干，任何「我省了 40% FLOPs」的结论都可能只是在补偿实现的低效。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是量纲分析：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 VLM 是 3B（SigLIP 400M + Gemma 2.6B），action expert 是 300M，双视角输入 512 个视觉 token。把这些数字代进 RTX 4090 的算力（约 91 TMAC/s）与带宽（1.01 TB/s），得到的下界是十几毫秒量级——远低于官方实现的 53.7 ms。既然理论下界与实测差 2–3 倍，问题就一定在实现里。</p><p>第二步是找开销的层级。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 每次推理要启动上千个核，Python 侧的启动开销首当其冲；而 Transformer 块内部没有动态分支，意味着核序列与缓冲区指针可以固定——这正是 CUDA graph 的适用前提。抓完这个「低垂果实」（约 2× 提速）之后，再看计算图本身有哪些等价改写；最后才下到单核内部调 tile 与融合。</p><p>第三步是知道什么时候停。作者用 roofline 加上实测的核间同步开销给出一个下界，说明剩余空间不超过 30%，从而把「继续优化」与「换个方向」的决策变成了可计算的问题。<strong>这个「先建下界再决定投入」的方法论，比论文里任何单条优化技巧都更值得借鉴。</strong></p><p>第四步是从系统结构反推新的可能性：既然 VLM 是计算受限、action expert 是带宽受限，二者并发执行就能同时吃满两种资源；而 action expert 本身可以每秒跑几百次——这直接指向一个多频率的控制架构。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>大模型跑不了实时，很大程度上不是因为它算得多，而是因为它等得多——等 Python 启动核、等核之间同步、等 cuBLAS 挑到一个次优的分块。把这些等待去掉之后，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在一张 4090 上离硬件极限只差 30%。更进一步：VLM 与 action expert 分别卡在算力和带宽这两种不同资源上，因此把它们并发跑几乎免费，这就给出了「一个模型、三个频率」的控制架构的物理基础。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>优化流水线（从 100+ ms 到 27.3 ms）</strong>：</p><ul><li><strong>消除 CPU 开销</strong>：用 CUDA graph 录制并回放整条核序列，核启动完全由 GPU 与驱动完成。前提是核代码与缓冲区指针每次运行不变——Transformer 块无动态分支，条件成立。约 2× 提速。</li><li><strong>简化计算图</strong>（三条等价改写，共省 7–8 ms）：把 RMS norm 的仿射参数吸收进下一个线性层（两者都线性）；折叠 action-time 编码器——动作值分支的两个连续线性层之间无非线性可直接合并，时间分支因推理只有 10 个时间步，可把线性层结果<strong>查表</strong>并一路融进 SiLU 前的偏置；融合 QKV 为一个大矩阵并把 RoPE 融进矩阵乘、权重预计算。</li><li><strong>核级优化</strong>：用 Triton 手调各 GEMM 的 tile 策略（省约 1.5 ms）；融合门控线性层，使两个 FFN 矩阵乘共享输入 tile 的加载、只写回合并结果（省 1.7 ms）；对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1152</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1152</span></span></span></span> 这种在 128 个 SM 上分不均的形状做<strong>部分 split-k</strong>（拆成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1152</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1024</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1152</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 两段写进同一个核，收益 &lt;0.1 ms）；把 bias、残差、激活融进 GEMM，RMS norm 先算 token 级统计再在下一个 GEMM 累加后归一（约 4 ms）。另注意 LLM 的注意力与 FFN 只需跑 17 次而非 18 次——只有 KV cache 传给 action expert，最后一层特征用不上（省约 0.7 ms）。</li><li><strong>系统外的坑</strong>：图像缩放若实现不当可达数毫秒，用相机 ISP 直出接近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span> 的分辨率（如 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">240</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">320</span></span></span></span>）并手写缩放代码，可压到 60 μs 以下；CPU↔GPU 拷贝用 pinned memory、CPU 缓冲区静态化以减抖动、相机帧零拷贝。</li></ul><p><strong>结果</strong>（RTX 4090，空 prompt，chunk 长 63）：naive torch 105.0/106.5/113.9 ms，openpi/jax 43.8/53.7/67.6 ms，本文 20.0/27.3/36.8 ms（1/2/3 视角）。</p><p><strong>真机验证</strong>：两个上下对齐的夹爪，上方释放马克笔、下方在正确时刻合拢接住（合拢耗时 60 ms ≈ 两帧）。30 FPS 720P USB 相机只看得到下方夹爪与笔，看不到释放动作；实测相机自身延迟约两帧（ISP 一帧 + USB 一帧），作者因此弃用了延迟超过 100 ms 的 RealSense。采集 600 段演示，录制时下方夹爪固定在释放后 200 ms 合拢。推理程序分相机线程（环形缓冲）、推理线程（永远取最新帧）、输出线程（按时间戳发送），10 次测试全部成功。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>Roofline 下界。</strong> 对一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 的 BF16 GEMM：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">roofline</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3324em;vertical-align:-0.9721em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size2">(</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">bandwidth</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">compute</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord"><span class="delimsizing size2">)</span></span></span></span></span></span></p><p>分子里只算第二个矩阵的内存搬运，因为网络里第一个矩阵与结果矩阵通常是激活、可以留在 L2，而权重太大必须从 HBM 读。RTX 4090 取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">bandwidth</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.01</span></span></span></span> TB/s；标称 BF16 为 82.6 TMAC/s，但实测卡的加速频率 2.79 GHz 对应 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">compute</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">91.4</span></span></span></span> TMAC/s。</p><p><strong>这条公式最有价值的推论是模型被分成了两个性质相反的部分。</strong> 取 LLM 中最大的一项（17 次 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2048</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32768</span></span></span></span>）：计算侧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">17</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2048</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">32768/91.4</span><span class="mord text"><span class="mord">T</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6.39</span></span></span></span> ms，带宽侧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">17</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2048</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">32768/1.01</span><span class="mord text"><span class="mord">T</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.26</span></span></span></span> ms，取大者 6.39 ms——<strong>计算受限</strong>。再取 action expert 中最大的一项（180 次 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">64</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1024</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8192</span></span></span></span>）：计算侧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.06</span></span></span></span> ms，带宽侧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.99</span></span></span></span> ms，取大者 2.99 ms——<strong>带宽受限</strong>。这里的 180 = 18 层 × 10 个去噪步，而每次的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 只有 64，因此 action expert 虽然只有 300M 参数，却要反复把权重从 HBM 拉进来，属于典型的低算术强度负载。</p><p>正因如此，两者并发执行能同时吃满算力与带宽，这才是 §6.1 里「并发跑 VLM + 16 次 AE 仍只用 32.7 ms」的物理原因，而不是某种调度技巧。</p><p><strong>同步开销。</strong> 作者用 1378 次简单核调用做微基准：PyTorch 逐核启动 13.81 ms（含 CPU 开销）、CUDA graph 2.61 ms、软件屏障 1.75 ms、完全融合无同步 0.89 ms，据此取 0.86 ms 作为同步成本。软件屏障的做法是：当启动的 block 数恰等于 SM 数时可保证所有 block 同时驻留，于是能用全局内存上的原子加做屏障。作者实测它比 CUDA graph 更快，但因为要求融合核的 grid 尺寸一致、寄存器与共享内存压力上升、代码体积增大，实际融合后反而变慢，故只用作下界的指示器。</p><p>把两部分相加得到最终下界 13.7 / 20.6 / 27.6 ms（1/2/3 视角），与实测 20.0 / 27.3 / 36.8 ms 相比，剩余空间至多约 30%。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>论文的「实验」有三类，性质完全不同，必须分开评估。</p><p><strong>一是延迟测量</strong>，也是全文最扎实的部分。表 1 的三档对照与图 2 的逐步分解（naive → +cuda graph → +simplified graph → 核优化）构成了完整的归因链。表 2 逐行给出每个 GEMM 的形状、调用次数、roofline、cuBLAS 时间、Triton 时间、所用策略、融合的标量算子与实际时间：视觉编码器 roofline 2.485 / cuBLAS 4.334 / Triton 3.957 / 实测 4.059；LLM 10.727 / 12.875 / 12.732 / 12.503；action expert 6.486 / 10.808 / 9.831 / <strong>11.001</strong>；合计 19.698 / 28.017 / 26.520 / 27.299。</p><p>这里要提醒读法：cuBLAS 与 Triton 两列只统计矩阵乘，而「实际」一列包含了融合进来的标量算子，因此总计 27.299 大于 Triton 列的 26.520、action expert 的 11.001 大于 cuBLAS 的 10.808，<strong>不能读作「优化后反而更慢」</strong>。但由此也可以看出：action expert 距其 roofline 有 1.70× 的差距，而 LLM 只有 1.17×——剩余的优化空间集中在那 180 次小 GEMM 上。另有两处小的文表不一致：§4.3 正文描述该 GEMM 用 split-2，表 2 该行记为 &quot;partial split-4&quot;；正文称计算图中共 1378 次 matmul，而按表 2 各行调用次数相加约为 1.33k。</p><p><strong>二是并发微基准</strong>，只有三行：顺序执行 VLM + 10 次 AE 为 27.3 ms，并发为 26.3 ms，并发 VLM + 16 次 AE 为 32.7 ms。<strong>并发本身只省了 1.0 ms</strong>；32.7 ms 这一行的含义是「在 33 ms 预算内最多能塞进 16 次 AE」，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">30</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">480</span></span></span></span> 即所谓 480 Hz 的来源。</p><p><strong>三是真机验证</strong>。10 次连续试验全部成功。作者对这一结果的自我评价异常诚实：「从学习的角度看这个结果是平凡的，换成 LeNet 甚至 SVM 也能做到；但从系统角度看，哪怕成功一次也验证了实现的低延迟。」他们还补充：人类接同样的下落笔，30 cm 是常见的反应距离下界，因此该系统的反应速度与普通人相当。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：(1) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 级 VLA 在单张 RTX 4090 上本来就能实时，此前的慢主要来自实现开销而非算力需求。(2) 三级优化——CUDA graph 去 CPU 开销（约 2×）、计算图等价改写（7–8 ms）、核级 tile/融合（约 7 ms）——把双视角从 105 ms 压到 27.3 ms。(3) 用 roofline 加实测同步开销建立 20.6 ms 的下界，说明剩余空间不超过 30%，为「何时停止优化」提供了判据。(4) VLM 计算受限、action expert 带宽受限，因此二者并发几乎免费，物理上支持 30 Hz 视觉 + 480 Hz 动作 + &lt;1 Hz 文本的三层控制回路。(5) 全流式推理目前只是设计草图，论文明确说明实现细节全部省略。</p><p><strong>3 句话版</strong>：把 VLA 的推理开销当作工程问题彻底榨干，双视角 27.3 ms、单视角 20.0 ms，均低于 33 ms 的实时门槛；接住下落的笔这一真机任务 10/10 成功，端到端反应时间与普通人相当；由 VLM/AE 的计算-带宽互补性出发，提出了一个尚未实现的多频率流式控制框架。</p><p><strong>1 句话版</strong>：VLA 跑不快不是因为它太大，是因为实现里全是等待。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>「把推理延迟降到 33 ms 以下」等价于「解锁了此前不可达的动态任务」</strong>。摘要与引言都建立在这个等价上，但全文用来支撑它的证据只有一个任务、10 次试验，而且这个任务的最优策略在论文自己的数据采集协议里就是一条常数——演示时下方夹爪永远在释放后 200 ms 合拢。换言之，模型需要学的只是「从画面估计笔还有多久到达」这一个标量，作者也明说了换成 LeNet 或 SVM 同样可行。</p><p>若这条假设不成立，论文的贡献边界应当收窄为：<strong>它证明了系统延迟可以做到多低，而没有证明低延迟的 VLA 能做什么</strong>。这不是吹毛求疵——真正需要 30 Hz 大模型的任务（比如在动态干扰下重新规划抓取点、跟踪被推开的物体），其难点恰恰在于每一帧都要重新做<strong>语义与几何</strong>判断，而这正是小模型做不到、也正是本任务不需要的部分。</p><p>另有两处使这条假设更难成立的细节。其一，端到端延迟里相机自身就占约两帧（≈67 ms），远大于优化省下的 26 ms；从 openpi 的 53.7 ms 降到 27.3 ms，在这个任务上兑现的收益不过是一帧。其二，全部延迟测量在<strong>空 prompt</strong> 下进行，而 VLA 的 L 就是语言；三视角配置已达 36.8 ms、越过 33 ms 门槛，而双臂机器人通常至少三个相机——作者在 §9.1 里也承认这一点。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且直接检验 §9 的实验，只需现成硬件：</p><ol><li>复现「接下落笔」的装置与 600 段演示，同时训练三个策略：(a) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；(b) 一个 ResNet-18 + 两层 MLP 的小模型（输入同为当前帧 + 前一帧）；(c) 一个只用像素阈值检测笔尖位置的纯几何基线。</li><li>在同一套推理框架下测三者的端到端反应时间与 50 次试验的成功率。</li><li>再造一个<strong>必须依赖语义</strong>的变体：桌面上同时释放马克笔与一支形状相近但不该接的记号笔（或用语言指令指定接哪一支），其余条件不变。</li><li>对每个策略再扫描推理延迟（人为插入 0/33/66/100 ms 延迟），画出「延迟—成功率」曲线。</li></ol><p>判据：若在原任务上 (b)(c) 与 (a) 同分，则 §9 的批评成立；若在语义变体上只有 (a) 能工作，且其成功率随注入延迟迅速下降，则「大模型 + 低延迟」的组合价值被真正证实——这正是论文缺失的那条证据。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>第一条攻击针对 <strong>480 Hz 这个数字</strong>。它不是任何被测系统的控制频率，而是从「33 ms 预算内能并发塞进 16 次 AE 前向」外推出来的吞吐量。要把它变成控制频率，论文自己列出的前提至少有三条尚未实现：流匹配必须被改写成逐步提交部分动作（作者提到 <a href="/notes/papers/2506.07339">RTC</a> 已有类似技术，但本文未实现）；高频力/电流信号必须以新 token 注入 AE，而这会改变模型输入分布、需要重新训练；轨迹缓冲区的融合规则「本报告不讨论」。§6.4 直接写明「实现细节全部省略」。因此一个反对者可以合理预测：一旦真的把力 token 接进去并要求 AE 在未完成去噪时就输出可执行动作，动作质量会显著下降，而这一代价从未被测量。判决实验是把 AE 改成部分提交模式后，在 LIBERO 之类的套件上比较完整去噪与逐步提交的成功率。</p><p>第二条攻击针对<strong>评测条件的选择</strong>。全部延迟在空 prompt、双视角、chunk 63、BF16、单请求下测得；而真实部署要带语言 prompt、常有三视角、可能需要并行处理多路。三视角 36.8 ms 已越线这一点，说明「<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 级 VLA 能实时」这一结论对配置相当敏感。此外作者提到显卡需要预热到稳定频率后才开始实验——这意味着长时间空闲后的第一次反应会更慢，而机器人恰恰常处于间歇工作状态。</p><p>第三，roofline 下界的构造方式对结论有利。作者用「各算子 roofline 之和」而非「整体 roofline」，并自行论证由于视觉编码器/LLM 计算受限、AE 带宽受限，跨算子重叠不会改变结论。这个论证对<strong>同类算子之间</strong>成立，但恰恰在 VLM 与 AE 的<strong>交界处</strong>不成立——而这正是 §6.1 用来论证并发有效的地方。两处论证方向相反，作者未做调和。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：本文把延迟当作纯粹的系统量来优化，把模型当作黑盒常量。但表 2 显示，优化到极限之后，<strong>action expert 占了 11.0 ms（40%），且离它自己的 roofline 还有 1.70×</strong>，原因是 10 个去噪步 × 18 层 = 180 次 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span> 的小 GEMM，算术强度极低。继续沿系统方向走，收益上限只剩 30%；而这 180 次调用的存在完全是模型设计的产物。</p><p><strong>新的 framing</strong>：不要问「怎么把去噪跑得更快」，而问「<strong>去噪步应该以什么频率消耗观测</strong>」。当前架构里，10 个去噪步共享同一个观测；但论文自己指出 AE 可以以 480 Hz 运行，而 VLM 只能以 30 Hz 更新。这意味着一个自然的新设计：把去噪步当作<strong>时间轴上的滚动窗口</strong>——第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个去噪步处理的不是「同一动作块的第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 次精修」，而是「比第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 步晚 2 ms 的传感器状态下的动作块」。此时去噪的迭代次数与控制频率解耦，模型在算术强度上也从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span> 的小 GEMM 变成可批处理的大 GEMM（同时精修多个时间偏移的块）。可借鉴的相邻工具是流式语音识别里的 chunk-wise 因果解码，以及模型预测控制中的滚动时域——两者都在「计算一次、消费多次」这个结构上有成熟处理。</p><p><strong>第一个实验</strong>：在仿真里把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 10 步去噪改成「每步都读取最新本体状态」的滚动版本（视觉特征仍 30 Hz 更新），在一个带外部扰动的任务（推动中的物体抓取）上比较：(a) 原版 10 步去噪 + 开环执行；(b) 滚动去噪；(c) 原版 + RTC 式部分提交。测量扰动施加后的恢复时间与成功率，同时记录 AE 的实际算术强度。可检验的预测是：滚动版在扰动下的恢复时间显著更短，且由于可以把多个时间偏移的块打包成一次大 GEMM，其单位动作的 GPU 时间反而低于原版——即<strong>延迟与吞吐的改善来自模型结构而非核优化</strong>，这正是本文方法论走到尽头之后唯一还剩的方向。</p>',55)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
